func Merge(in [][2]int) [][2]int {
    if len(in) == 0 {
        return in
    }

    sort.Slice(in, func(i, j int) bool {
        return in[i][0] < in[j][0]
    })

    merged := make([][2]int, 0)
    current := in[0]

    for _, interval := range in[1:] {
        if interval[0] <= current[1] {
            if interval[1] > current[1] {
                current[1] = interval[1]
            }
        } else {
            merged = append(merged, current)
            current = interval
        }
    }

    merged = append(merged, current)
    return merged
}

