func Caesar(s string, n int) string {
	var result strings.Builder
	for _, r := range s {
		if unicode.IsLetter(r) {
			offset := rune('a')
			if unicode.IsUpper(r) {
				offset = rune('A')
			}
			result.WriteRune((r-offset+rune(n))%26 + offset)
		} else {
			result.WriteRune(r)
		}
	}
	return result.String()
}

