func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	results := make(chan int, len(nums))
	var wg sync.WaitGroup

	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for num := range jobs {
				results <- num
			}
		}()
	}

	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	go func() {
		wg.Wait()
		close(results)
	}()

	sum := 0
	for result := range results {
		sum += result
	}

	return sum
}

