func CountUntil(ctx context.Context, ch <-chan int) int {
	var count int
	var mu sync.Mutex
	done := make(chan struct{})

	go func() {
		for {
			select {
			case <-ctx.Done():
				close(done)
				return
			case val, ok := <-ch:
				if !ok {
					close(done)
					return
				}
				mu.Lock()
				count++
				mu.Unlock()
			}
		}
	}()

	<-done
	return count
}

