func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buf := make([]byte, size)
	for {
		n, err := r.Read(buf)
		if err != nil && err != io.EOF {
			return nil, err
		}
		if n == 0 {
			break
		}
		chunks = append(chunks, buf[:n])
		if err == io.EOF {
			break
		}
	}
	return chunks, nil
}

